import subprocess
# Get all FUNC symbols sorted by address
result = subprocess.run(['readelf', '-Ws', 'symbols/libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
syms = []
for line in result.stdout.split('\n'):
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC' and parts[1] != '00000000':
        try:
            addr = int(parts[1], 16)
            name = parts[7]
            if not name.startswith('\$'):
                syms.append((addr, name))
        except: pass
syms.sort()

targets = [0x2f4b20, 0x2f4c84, 0x2c1a40]
for t in targets:
    best = None
    for addr, name in syms:
        if addr <= t:
            best = (addr, name)
        else:
            break
    if best:
        print(f'0x{t:x} -> {best[1]} + 0x{t - best[0]:x} (base: 0x{best[0]:x})')
    else:
        print(f'0x{t:x} -> ???')
"

