import subprocess
# The thunk section contains branch instructions. Let's look at what functions they branch to.
# Use readelf to dump .rela sections or just parse the thunk content
# Actually, let's use a different approach - search DWARF info
result = subprocess.run(['readelf', '--debug-dump=info', 'symbols/libmonosgen-2.0.so.dbg'], capture_output=True, text=True)
lines = result.stdout.split('\n')

# Find subprograms whose address ranges contain our targets
import re
current_func = None
current_low = None
for i, line in enumerate(lines):
    if 'DW_TAG_subprogram' in line:
        current_func = None
        current_low = None
    if 'DW_AT_name' in line and current_func is None:
        m = re.search(r'DW_AT_name\s*:\s*(.+)', line)
        if m:
            current_func = m.group(1).strip()
    if 'DW_AT_low_pc' in line:
        m = re.search(r'0x([0-9a-f]+)', line)
        if m:
            current_low = int(m.group(1), 16)
    if 'DW_AT_high_pc' in line and current_low is not None and current_func:
        m = re.search(r'0x([0-9a-f]+)', line)
        if m:
            val = int(m.group(1), 16)
            # high_pc can be absolute or offset
            high = val if val > current_low else current_low + val
            for target in [0x2f4b20, 0x2f4c84]:
                if current_low <= target < high:
                    print(f'0x{target:x} is in {current_func} (0x{current_low:x}-0x{high:x})')
" 2>&1 | head -20

